
/* ================= DRIVE ================= */
const DRV={sp:'org',view:'list',sel:new Set(),slide:0,rot:0,crop:false};
Object.defineProperty(DRV,'space',{get:()=>DRV.sp==='org'?oname():'Personal'});
const FOLD=[{id:'delivery',n:'Delivery',p:'root'},{id:'sops',n:'SOPs',p:'root',lock:1},{id:'templates',n:'Templates',p:'root'},{id:'brand',n:'Brand assets',p:'root'},{id:'finance',n:'Finance',p:'root'},{id:'onb',n:'Onboarding',p:'delivery'}];
let DF=[{n:'Client onboarding SOP',t:'doc',o:'TR',m:'Today, 10:42',s:'84 KB',st:1,f:'sops',e:'sop'},{n:'Q4 content calendar',t:'sheet',o:'AR',m:'Yesterday',s:'31 KB',f:'delivery',e:'cal'},{n:'Discovery call script',t:'doc',o:'TR',m:'20 Oct',s:'22 KB',st:1,f:'delivery',e:'brief'},{n:'Kickoff deck',t:'slides',o:'BK',m:'18 Oct',s:'4.1 MB',f:'templates',e:'deck'},{n:'Ad creative, hero',t:'image',o:'AR',m:'16 Oct',s:'2.3 MB',f:'brand',e:'hero'},{n:'Retainer agreement',t:'pdf',o:'TR',m:'9 Oct',s:'210 KB',f:'finance'},{n:'Delivery timeline',t:'sheet',o:'BK',m:'2 Oct',s:'48 KB',f:'delivery',e:'cal'}];
const TRASH=[['Old proposal draft','doc','12 days left'],['Logo v1.png','image','25 days left']];
const FT2={doc:'DOC',sheet:'XLS',slides:'PPT',image:'IMG',pdf:'PDF'};
const DNAV=()=>[['drive/home','Home','home'],['drive/mydrive','My Drive','drive',null,null,'My Drive'],['drive/shared','Shared with me','team',3,null,'Shared'],['drive/drives','Shared drives','layers'],['drive/recent','Recent','clock'],['drive/starred','Starred','star'],['drive/trash','Trash','trash']];
function dShell(cur,body,crumbs){const top=`<div style="display:grid;gap:4px;margin:-6px 0 12px"><span class="over" style="padding:0 4px 4px">Space</span>${[['org',oname(),mark(org(),26)],['personal','Personal',`<span class="avatar" style="width:26px;height:26px;font-size:10px">TR</span>`]].map(([k,l,m])=>`<button class="linkrow" style="min-height:44px;padding:4px 8px;${DRV.sp===k?'background:var(--surface);box-shadow:var(--sh1)':''}" data-act="dsp:${k}" aria-pressed="${DRV.sp===k}">${m}<span class="main"><b style="font-size:14px">${l}</b></span>${DRV.sp===k?ic('check',16,'',2.4):''}</button>`).join('')}</div><button class="btn primary" style="margin-bottom:12px;width:100%" data-act="dnew">${ic('plus',18,'',2.2)}New</button>`;
return shell('drive',{nav:DNAV(),cur,body,crumbs:crumbs||[['Drive']],sideTop:top,sideMid:`<div class="storage">${DRV.sp==='personal'?'<b style="color:var(--text)">Private to you</b><p style="margin-top:4px">Admins can’t open your Personal space.</p>':`<b style="color:var(--text)">Storage</b><div class="bar"><i></i></div>4.2 GB of 15 GB used`}</div><p class="hint" style="padding:10px 6px 0">Client files live in Clients. Project docs live in Projects.</p>`})}
const fRows=L=>DRV.view==='grid'?`<div class="fgrid">${L.map(f=>`<button class="fcard" data-act="${f.e?`nav:drive/edit/${f.t}/${f.e}`:'dprev:'+DF.indexOf(f)}"><div class="thumb" data-t="${f.t}"></div><div class="meta"><span class="ft ${f.t}">${FT2[f.t]}</span><div style="min-width:0"><b>${esc(f.n)}</b><small>${f.m}</small></div></div></button>`).join('')}</div>`
:`<div class="tblwrap"><table class="tbl ftab"><thead><tr><th style="width:52px"><span class="sr">Select</span></th><th>Name</th><th class="hide-m">Owner</th><th>Modified</th><th class="hide-m">Size</th><th style="width:96px"><span class="sr">Actions</span></th></tr></thead><tbody>${L.map(f=>{const i=DF.indexOf(f);return `<tr aria-selected="${DRV.sel.has(i)}" class="${f.fresh?'fresh':''}"><td data-l=""><button class="sq" role="checkbox" aria-checked="${DRV.sel.has(i)}" aria-label="Select ${esc(f.n)}" data-act="dsel:${i}"><i>${ic('check',13,'',3)}</i></button></td><td class="t1"><button class="fname" data-act="${f.e?`nav:drive/edit/${f.t}/${f.e}`:'dprev:'+i}"><span class="ft ${f.t}">${FT2[f.t]}</span>${esc(f.n)}</button></td><td class="hide-m" data-l="Owner">${av(f.o)}</td><td data-l="Modified">${f.m}</td><td class="hide-m mono" data-l="Size" style="font-size:13px">${f.s}</td><td data-l=""><span style="display:flex"><button class="iconbtn star ${f.st?'on':''}" aria-pressed="${!!f.st}" aria-label="Star" data-act="dstar:${i}">${f.st?ic('star',18).replace('fill="none"','fill="currentColor"'):ic('star',18)}</button><button class="iconbtn" aria-label="Details" data-act="dprev:${i}">${ic('info',18)}</button></span></td></tr>`}).join('')}</tbody></table></div>`;
const dTools=title=>`<div class="dtools"><h1>${title}</h1><button class="chip" data-act="noop">${ic('filter',16)}Type</button><button class="chip hide-m" data-act="noop">${ic('team',16)}People</button><div class="tog" role="group" aria-label="View"><button aria-pressed="${DRV.view==='list'}" aria-label="List view" data-act="dview:list">${ic('list',18)}</button><button aria-pressed="${DRV.view==='grid'}" aria-label="Grid view" data-act="dview:grid">${ic('tiles',18)}</button></div><button class="btn ghost" data-act="newfolder">${ic('fplus',18)}<span class="hide-m">New folder</span></button><button class="btn ink" data-act="dupload">${ic('upload',18)}<span class="hide-m">Upload</span></button></div>`;
const selbar=()=>DRV.sel.size?`<div class="selbar"><b>${DRV.sel.size} selected</b><button data-act="dshare">${ic('share',18)}<span>Share</span></button><button data-act="toast:Download started.">${ic('download',18)}<span>Download</span></button><button data-act="toast:Pick a folder in the same space.">${ic('move',18)}<span>Move</span></button><button data-act="ddel">${ic('trash',18)}<span>Delete</span></button><button data-act="dclear" aria-label="Clear selection">${ic('x',18)}</button></div>`:'';
const drop=`<div class="dropov" id="dropov" aria-hidden="true"><div>${plate(app('drive'),96)}<h2>Drop to upload</h2><p class="tx2">Files go into the folder you’re viewing.</p></div></div>`;
VIEWS.drive=p=>{const pg=p[0]||'home';
if(pg==='edit')return editor(p[1],p[2]);
if(DRV.sp==='personal'&&['home','mydrive'].includes(pg))return dShell('drive/'+pg,`${dTools('My Drive <span>Personal</span>')}<div class="notice plain" style="margin-bottom:16px">${ic('lock',18)}<span>Your Personal space is private. Share a file to let someone in.</span></div>${fRows(DF.slice(2,4))}${selbar()}${drop}`);
if(pg==='home')return dShell('drive/home',`${dTools('Home')}<p class="over" style="margin-bottom:12px">Suggested for you</p><div class="sugg">${[0,1,3,4].map(i=>{const f=DF[i];return `<button class="fcard" data-act="${f.e?`nav:drive/edit/${f.t}/${f.e}`:'dprev:'+i}"><div class="thumb" data-t="${f.t}"></div><div class="meta"><span class="ft ${f.t}">${FT2[f.t]}</span><div style="min-width:0"><b>${esc(f.n)}</b><small>You opened ${f.m.toLowerCase()}</small></div></div></button>`}).join('')}</div>
<p class="over" style="margin-bottom:12px">Folders</p><div class="folders">${FOLD.filter(f=>f.p==='root').map(f=>`<button class="folder" data-act="nav:drive/f/${f.id}">${ic('folder',20)}${f.n}${f.lock?ic('lock',14):''}</button>`).join('')}</div>
<p class="over" style="margin-bottom:12px">Recent files</p>${fRows(DF)}${selbar()}${drop}`);
if(pg==='mydrive')return dShell('drive/mydrive',`${dTools(`My Drive <span>${oname()}</span>`)}<div class="folders">${FOLD.filter(f=>f.p==='root').map(f=>`<button class="folder" data-act="nav:drive/f/${f.id}">${ic('folder',20)}${f.n}</button>`).join('')}</div>${fRows(DF)}${selbar()}${drop}`,[['Drive'],['My Drive']]);
if(pg==='f'){const f=FOLD.find(x=>x.id===p[1])||FOLD[0];const kids=FOLD.filter(x=>x.p===f.id),files=DF.filter(x=>x.f===f.id);return dShell('drive/mydrive',`${dTools(`${f.n} <span>My Drive ${ic('right',14)} ${f.n}</span>`)}${f.lock?`<div class="notice plain" style="margin-bottom:16px">${ic('lock',18)}<span><b>Owner protected.</b> Everyone can read these SOPs. Only the owner can change or remove them.</span></div>`:''}${kids.length?`<div class="folders">${kids.map(k=>`<button class="folder" data-act="nav:drive/f/${k.id}">${ic('folder',20)}${k.n}</button>`).join('')}</div>`:''}${files.length?fRows(files):emptyS(stack('mini-stack'),'This folder is empty','Drop files here, or create something new.',`<button class="btn primary" data-act="dnew">${ic('plus',18,'',2.2)}New</button>`)}${selbar()}${drop}`,[['Drive'],['My Drive','drive/mydrive'],[f.n]])}
if(pg==='shared')return dShell('drive/shared',`${dTools('Shared with me')}${fRows(DF.slice(1,4))}${selbar()}`,[['Drive'],['Shared with me']]);
if(pg==='drives')return dShell('drive/drives',`${head('Shared drives',`Owned by ${oname()}, not by one person. Admins manage who gets in.`)}<div class="cardgrid">${[['Delivery','#2B63F6',14],['Marketing','#E9488F',8],['SOPs','#13A592',5,1]].map(([n,c,k,l])=>`<button class="card" data-act="nav:drive/f/${n==='SOPs'?'sops':'delivery'}"><span class="wic" style="--c:${c}">${ic('layers',22)}</span><h3>${n}${l?' '+ic('lock',14):''}</h3><div class="foot">${k} files · ${avs(['TR','AR','BK'])}</div></button>`).join('')}</div>`,[['Drive'],['Shared drives']]);
if(pg==='recent')return dShell('drive/recent',`${dTools('Recent')}${fRows(DF)}${selbar()}`,[['Drive'],['Recent']]);
if(pg==='starred')return dShell('drive/starred',`${dTools('Starred')}${fRows(DF.filter(f=>f.st))}${selbar()}`,[['Drive'],['Starred']]);
if(pg==='trash')return dShell('drive/trash',`${head('Trash','Deleted items stay here for 30 days. History and owner are kept.')}<div class="tblwrap"><table class="tbl"><thead><tr><th>Name</th><th>Time left</th><th></th></tr></thead><tbody>${TRASH.map(([n,t,l])=>`<tr><td class="t1"><span class="fname"><span class="ft ${t}">${FT2[t]}</span>${n}</span></td><td data-l="Time left">${l}</td><td data-l=""><span style="display:flex;gap:6px;justify-content:flex-end"><button class="btn ghost sm" data-act="toast:Restored to its folder.:ok">${ic('restore',16)}Restore</button><button class="btn quiet sm" data-act="toast:Only an owner can delete forever.">Delete forever</button></span></td></tr>`).join('')}</tbody></table></div>`,[['Drive'],['Trash']]);
return dShell('drive/home','')};
function dDetails(i,tab='details'){const f=DF[i];openDrawer(`<div class="drw-h"><span class="ft ${f.t}">${FT2[f.t]}</span><b class="grow" style="white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(f.n)}</b><button class="iconbtn" data-act="drawerx" aria-label="Close">${ic('x')}</button></div>${tabs([['details','Details'],['access','Manage access'],['versions','Versions']].map(x=>x),tab,'').replace(/data-act="nav:/g,`data-act="dtab:${i}|`)}
${tab==='details'?`<div class="thumb" data-t="${f.t}" style="border-radius:16px;border:var(--bw) solid var(--line)"></div><dl class="kvl"><dt>Owner</dt><dd>${PEOPLE[f.o][0]}</dd><dt>Modified</dt><dd>${f.m}</dd><dt>Size</dt><dd>${f.s}</dd><dt>Location</dt><dd>${DRV.space} › ${(FOLD.find(x=>x.id===f.f)||{n:'My Drive'}).n}</dd><dt>Who can open</dt><dd>Everyone in ${oname()} (inherited)</dd></dl><div style="display:flex;gap:10px;flex-wrap:wrap"><button class="btn ink" data-act="${f.e?`nav:drive/edit/${f.t}/${f.e}`:'toast:Opens in the viewer.'}">${ic('eye',18)}Open</button><button class="btn ghost" data-act="dtab:${i}|access">${ic('share',18)}Share</button></div>`:''}
${tab==='access'?`<label class="inp" style="margin-bottom:14px">${ic('user',18)}<input placeholder="Add people or groups"></label>${[['TR','Owner',''],['AR','Editor','Direct'],['BK','Viewer','From folder “Delivery”']].map(([k,r,w])=>`<div class="linkrow" style="padding:6px 0">${av(k)}<span class="main"><b>${PEOPLE[k][0]}</b><small>${w||'Owner'}</small></span>${r==='Owner'?'<span class="muted" style="font-size:13px">Owner</span>':`<select class="sel" aria-label="Role"><option ${r==='Viewer'?'selected':''}>Viewer</option><option ${r==='Editor'?'selected':''}>Editor</option><option>Remove</option></select>`}</div>`).join('')}<div class="notice plain" style="margin:14px 0;font-size:13.5px">${ic('info',16)}<span>Effective access: 3 people. Changes are logged. Changing access doesn’t let an admin read the file.</span></div><button class="btn primary full" data-act="toast:Access saved and logged.:ok">Save</button>`:''}
${tab==='versions'?[['v4','Today, 10:42','TR','Current'],['v3','20 Oct','AR',''],['v2','12 Oct','TR',''],['v1','1 Oct','TR','Original']].map(([v,d,k,l])=>`<div class="ver" style="margin-bottom:8px"><b class="mono">${v}</b><span style="flex:1">${d} · ${PEOPLE[k][0].split(' ')[0]}${l?` <span class="pill" style="height:22px">${l}</span>`:''}</span>${l==='Current'?'':`<button class="btn quiet sm" data-act="toast:Restored as a new version. Nothing is lost.:ok">Restore</button>`}</div>`).join(''):''}`)}
/* ---------- editors ---------- */
function edTop(t,title,loc){const T={doc:['DOC','doc'],sheet:['XLS','sheet'],slides:['PPT','slides'],image:['IMG','image']}[t];return `<div class="ov-top"><button class="iconbtn" data-act="nav:drive/home" aria-label="Back to Drive">${ic('right',20).replace('<svg','<svg style="transform:scaleX(-1)"')}</button><span class="ft ${T[1]}" style="width:38px;height:38px">${T[0]}</span><div class="grow"><input class="drw-title" style="font-size:16px;padding:2px 0" value="${title}" aria-label="File name"><small>${loc}</small></div><span class="savest hide-m" id="savest"><i></i>Saved</span><span class="hide-m">${avs(['AR','BK'])}</span><button class="btn ghost sm hide-m" data-act="toast:Version history: restore any version, nothing is lost.">${ic('hist',16)}Versions</button><button class="btn primary sm" data-act="dshare">${ic('share',16)}Share</button></div>`}
const SH={cols:['Week','Channel','Topic','Posts','Reach','Leads'],d:[['1','Instagram','Quiz launch','5','4200','38'],['2','Instagram','Client win','4','3900','31'],['3','YouTube','Funnel teardown','1','2600','22'],['4','Email','Case study','2','1800','40'],['5','Instagram','Myths','5','5100','44'],['6','LinkedIn','Offer post','3','1400','12']],f:{}};
SH.d.push(['Total','','','=SUM(D2:D7)','=SUM(E2:E7)','=SUM(F2:F7)']);
const cn=i=>String.fromCharCode(65+i);
function shVal(r,c){const v=(SH.d[r]||[])[c]??'';if(!String(v).startsWith('='))return v;try{let ex=v.slice(1).toUpperCase().replace(/(SUM|AVERAGE)\(([A-Z])(\d+):([A-Z])(\d+)\)/g,(m,fn,c1,r1,c2,r2)=>{let a=[];for(let cc=c1.charCodeAt(0)-65;cc<=c2.charCodeAt(0)-65;cc++)for(let rr=+r1;rr<=+r2;rr++)a.push(+shVal(rr-2,cc)||0);const s=a.reduce((x,y)=>x+y,0);return fn==='SUM'?s:(s/a.length).toFixed(2)}).replace(/([A-Z])(\d+)/g,(m,c1,r1)=>+shVal(+r1-2,c1.charCodeAt(0)-65)||0);return /^[\d+\-*/().\s]+$/.test(ex)?String(Function('return '+ex)()):'#ERR'}catch(e){return '#ERR'}}
const shGrid=()=>`<table class="sheet"><thead><tr><th></th>${Array.from({length:9},(_,i)=>`<th>${cn(i)}</th>`).join('')}</tr></thead><tbody><tr class="hdr-r"><td>1</td>${Array.from({length:9},(_,i)=>`<td><input value="${SH.cols[i]||''}" data-r="-1" data-c="${i}" aria-label="${cn(i)}1"></td>`).join('')}</tr>${Array.from({length:22},(_,r)=>`<tr class="${r===6?'hdr-r':''}"><td>${r+2}</td>${Array.from({length:9},(_,c)=>{const v=shVal(r,c);return `<td class="${/^-?[\d.]+$/.test(v)?'num':''}"><input value="${esc(v)}" data-r="${r}" data-c="${c}" aria-label="${cn(c)}${r+2}"></td>`}).join('')}</tr>`).join('')}</tbody></table>`;
const SL=[['Kick-off','Harry Kaye PT · quiz funnel','dark'],['What we heard','Busy mums who used to train and lost the habit.','light'],['The plan','Reel → quiz → result → booking → call.','dark'],['Timeline','Copy by 24 Oct. Build by 14 Nov. Launch late Nov.','light'],['Next steps','Approve strategy v2 by Friday.','dark']];
const slideHTML=(s,ed)=>`<div class="sl ${s[2]==='light'?'light':''}"><span class="pill brand chip">Layer2Funnels</span><h2 ${ed?'contenteditable="true"':''}>${s[0]}</h2><p ${ed?'contenteditable="true"':''}>${s[1]}</p></div>`;
function editor(t,id){
if(t==='doc')return `${edTop('doc',{sop:'Client onboarding SOP',brief:'Project brief',copy:'Quiz page copy v2'}[id]||'Untitled document',`${DRV.space} › Delivery`)}<div class="ed-tools" role="toolbar" aria-label="Formatting"><button aria-label="Undo" data-act="cmd:undo">${ic('undo',18)}</button><button aria-label="Redo" data-act="cmd:redo">${ic('redo',18)}</button><span class="vs"></span><select class="sel" aria-label="Text style" data-cmd="formatBlock"><option value="p">Normal text</option><option value="h2">Heading</option><option value="h1">Title</option></select><span class="vs"></span>${[['bold','Bold','bold'],['italic','Italic','italic'],['under','Underline','underline'],['ul','Bullet list','insertUnorderedList']].map(([i,l,c])=>`<button aria-label="${l}" data-act="cmd:${c}">${ic(i,18)}</button>`).join('')}<button aria-label="Link" data-act="toast:Add a link.">${ic('link',18)}</button><button aria-label="Image" data-act="toast:Insert an image from Drive or your computer.">${ic('imgI',18)}</button><span class="vs"></span><button aria-label="Comment" data-act="toast:Select text, then comment.">${ic('msg',18)}</button></div>
<div class="edbody"><nav class="outline" aria-label="Outline"><p class="over" style="padding:6px 10px">Outline</p>${['Purpose','Before the call','During onboarding','Handover'].map(h=>`<button data-act="noop">${h}</button>`).join('')}</nav><article class="docpage"><div contenteditable="true" id="doced"><h1>Client onboarding SOP</h1><p class="muted">Owner protected · v4 · approved by Tabish</p><h2>Purpose</h2><p>Every new client gets the same calm, clear start. This is how we do it.</p><h2>Before the call</h2><ul><li>Create the client in Clients. It starts in Brand Base.</li><li>Prepare the Brand Base form.</li><li>Book the kick-off call.</li></ul><h2>During onboarding</h2><p>Walk through the five stages. Explain that approvals happen in the Portal once it’s live.</p><h2>Handover</h2><p>Assign the account lead and strategist. Post the first update.</p></div></article>
<aside class="side-panel" style="display:grid;gap:12px;position:sticky;top:130px"><section class="panel" style="padding:16px"><p class="sec-t" style="margin-top:0">${ic('msg',16)}Comments</p><div class="comment">${av('AR')}<div class="bub" style="font-size:13.5px">Should we add the welcome video here?<br><small>Yesterday</small></div></div></section></aside></div>`;
if(t==='sheet')return `${edTop('sheet','Q4 content calendar',`${DRV.space} › Delivery`)}<div class="ed-tools" role="toolbar" aria-label="Sheet tools" style="top:64px">${[['undo','Undo'],['redo','Redo']].map(([i,l])=>`<button aria-label="${l}" data-act="noop">${ic(i,18)}</button>`).join('')}<span class="vs"></span><button aria-label="Bold">${ic('bold',18)}</button><button aria-label="Currency" data-act="noop" style="font-weight:700">$</button><button aria-label="Percent" data-act="noop" style="font-weight:700">%</button><button aria-label="Sum" data-act="toast:Type =SUM(A2:A7) in any cell." style="font-weight:700">Σ</button><span class="vs"></span><button aria-label="Chart" data-act="toast:Charts insert from the selected range.">${ic('chart',18)}</button><button aria-label="Filter" data-act="noop">${ic('filter',18)}</button></div><div class="fbar" style="top:120px"><span class="cellref" id="cref">A1</span><span class="fx">fx</span><input id="fbar" aria-label="Formula bar" placeholder="Value or formula, e.g. =SUM(E2:E7)"></div><div class="sheetwrap" id="shw">${shGrid()}</div><div class="stabs">${['October','November','Ideas'].map((s,i)=>`<button aria-pressed="${!i}" data-act="noop">${s}</button>`).join('')}<button data-act="toast:New sheet added.">${ic('plus',16)}</button></div>`;
if(t==='slides')return `${edTop('slides','Kickoff deck',`${DRV.space} › Templates`)}<div class="ed-tools" role="toolbar" aria-label="Slide tools" style="top:64px"><button aria-label="Undo">${ic('undo',18)}</button><button aria-label="Redo">${ic('redo',18)}</button><span class="vs"></span><button aria-label="Text box" data-act="noop">${ic('text',18)}</button><button aria-label="Image" data-act="noop">${ic('imgI',18)}</button><button aria-label="Shape" data-act="noop">${ic('shape',18)}</button><span class="vs"></span><select class="sel" aria-label="Theme"><option>Signal theme</option><option>Paper theme</option></select><span class="vs"></span><button class="btn ink sm" style="width:auto;padding:0 12px" data-act="present">${ic('play',16)}Present</button></div>
<div class="slides"><nav class="snav" aria-label="Slides">${SL.map((s,i)=>`<button data-act="slide:${i}" aria-current="${i===DRV.slide}"><span>${i+1}</span><span class="th" style="container-type:inline-size">${slideHTML(s)}</span></button>`).join('')}<button class="chip" data-act="toast:Slide added.">${ic('plus',16)}Slide</button></nav><div><div class="stage16">${slideHTML(SL[DRV.slide],1)}</div><div class="notes" contenteditable="true" aria-label="Speaker notes">Speaker notes: thank Harry for the Brand Base answers. Keep this under 2 minutes.</div></div></div>`;
if(t==='image')return `${edTop('image','Ad creative, hero',`${DRV.space} › Brand assets`)}<div class="imged"><div class="itools" role="toolbar" aria-label="Image tools">${[['cursor','Move','move'],['crop','Crop','crop'],['rotate','Rotate 90°','rotate'],['text','Text','text'],['pen','Markup','pen'],['sliders','Adjust','adjust']].map(([i,l,k])=>`<button aria-label="${l}" title="${l}" aria-pressed="${(k==='crop'&&DRV.crop)||(k==='move'&&!DRV.crop)}" data-act="itool:${k}">${ic(i,20)}</button>`).join('')}<span style="height:12px"></span><button aria-label="Undo" data-act="noop">${ic('undo',20)}</button></div>
<div class="icanvas"><div class="ipic" id="ipic" style="transform:rotate(${DRV.rot}deg)">${DRV.crop?'<div class="cropbox"><i></i><i></i><i></i><i></i></div>':''}<span class="mk">New: Quiz is live</span></div></div>
<div class="ipanel"><p class="sec-t" style="margin:0">Adjust</p>${[['br','Brightness',100],['ct','Contrast',100],['sa','Saturation',100]].map(([k,l,v])=>`<label class="rng">${l}<input type="range" min="40" max="160" value="${v}" class="iadj" data-k="${k}"></label>`).join('')}<p class="sec-t" style="margin:6px 0 0">Size</p><div class="row2"><div class="field"><label for="iw">Width</label><input id="iw" value="1600"></div><div class="field"><label for="ih">Height</label><input id="ih" value="1200"></div></div>${DRV.crop?`<button class="btn ink" data-act="itool:move">${ic('check',18)}Apply crop</button>`:''}<div class="notice plain" style="font-size:13px">${ic('hist',16)}<span>Saving creates a new version. The original is always kept.</span></div><button class="btn primary" data-act="toast:Saved as version 3. Original kept.:ok">Save</button></div></div>`;
return edTop('doc','Untitled','')}
Object.assign(ACT,{
dsp:v=>{DRV.sp=v;DRV.sel.clear();draw()},dview:v=>{DRV.view=v;draw()},
dsel:v=>{const i=+v;DRV.sel.has(i)?DRV.sel.delete(i):DRV.sel.add(i);draw()},dclear:()=>{DRV.sel.clear();draw()},
dstar:v=>{DF[+v].st=!DF[+v].st;draw()},dprev:v=>dDetails(+v),dtab:v=>{const[i,t]=v.split('|');dDetails(+i,t)},
dshare:()=>{dDetails(DRV.sel.size?[...DRV.sel][0]:0,'access')},
ddel:()=>dlg({title:`Move ${DRV.sel.size} item${DRV.sel.size>1?'s':''} to Trash?`,body:'You can restore them for 30 days. Owner and history are kept.',acts:[['Cancel','noop'],['Move to Trash','ddel2','ink']]}),
ddel2:()=>{DF=DF.filter((_,i)=>!DRV.sel.has(i));DRV.sel.clear();draw();toast('Moved to Trash.','ok')},
dnew:()=>dlg({title:'Create new',body:`<div class="grid2" style="gap:8px;margin-top:12px">${[['fplus','Folder','newfolder','#7C818D'],['doc','Document','nav:drive/edit/doc/new','#2B63F6'],['sheetI','Sheet','nav:drive/edit/sheet/new','#14A493'],['slideI','Slides','nav:drive/edit/slides/new','#F07C1A'],['imgI','Image','nav:drive/edit/image/new','#6B4FF0'],['upload','Upload files','dupload','#16171B']].map(([i,l,a,c])=>`<button class="linkrow" style="border:var(--bw) solid var(--line)" data-act="${a}"><span class="wic" style="--c:${c};width:40px;height:40px">${ic(i,20)}</span><span class="main"><b>${l}</b></span></button>`).join('')}</div><p class="hint" style="margin-top:12px">Creates in ${DRV.space}. You’ll see the owner and location before saving.</p>`,acts:[['Close','noop']]}),
mkfolder:()=>{const n=($('#nf')?.value||'').trim()||'Untitled folder';FOLD.push({id:'f'+Date.now(),n,p:RT.a==='drive'&&RT.p[0]==='f'?RT.p[1]:'root'});toast(`Folder “${n}” created.`,'ok');if(RT.a==='drive')draw()},
dupload:()=>dUpload(['Client offboarding SOP.docx','Retainer checklist.xlsx']),
slide:v=>{DRV.slide=+v;draw()},present:()=>{const e=$('.stage16');e?.requestFullscreen?.().catch(()=>toast('Presenting full screen.'))},
itool:v=>{if(v==='rotate'){DRV.rot=(DRV.rot+90)%360;$('#ipic').style.transform=`rotate(${DRV.rot}deg)`;return}DRV.crop=v==='crop';if(v==='move'||v==='crop')draw();else toast({text:'Click the image to add text.',pen:'Draw on the image to mark it up.',adjust:'Use the sliders on the right.'}[v])}
});
function dUpload(names){const t=document.createElement('div');t.className='toast up';t.innerHTML=`<div class="up-h">${ic('upload',18)}<b>Uploading ${names.length} file${names.length>1?'s':''}</b></div>`+names.map(n=>`<div class="up-r"><span>${esc(n)}</span><i><em></em></i></div>`).join('');$('#toasts').append(t);let p=0;const bars=$$('em',t);const iv=setInterval(()=>{p+=Math.random()*16+8;bars.forEach((b,i)=>b.style.width=Math.max(0,Math.min(100,p-i*14))+'%');if(p>=100+names.length*14){clearInterval(iv);$('.up-h',t).innerHTML=`${ic('check',18,'',2.4)}<b>${names.length} uploaded</b>`;names.forEach(n=>DF.unshift({n:n.replace(/\.\w+$/,''),t:/xls|csv/i.test(n)?'sheet':/pdf/i.test(n)?'pdf':/png|jpe?g|gif|webp|svg/i.test(n)?'image':/ppt|key/i.test(n)?'slides':'doc',o:'TR',m:'Just now',s:'·',fresh:1,f:RT.p[1]||'delivery'}));DRV.sel.clear();if(RT.a==='drive')draw();DF.forEach(f=>delete f.fresh);setTimeout(()=>{t.classList.add('out');setTimeout(()=>t.remove(),300)},2600)}},170)}
INPUTC.iadj=()=>{const v={};$$('.iadj').forEach(r=>v[r.dataset.k]=r.value);$('#ipic').style.filter=`brightness(${v.br}%) contrast(${v.ct}%) saturate(${v.sa}%)`};
let curCell=null;
document.addEventListener('focusin',e=>{const i=e.target;if(i.closest?.('.sheet')&&i.dataset.r!=null){curCell=i;const r=+i.dataset.r,c=+i.dataset.c;$('#cref').textContent=cn(c)+(r+2);$('#fbar').value=r<0?SH.cols[c]||'':(SH.d[r]||[])[c]??''}});
document.addEventListener('change',e=>{const i=e.target;if(i.closest?.('.sheet')&&i.dataset.r!=null){const r=+i.dataset.r,c=+i.dataset.c;if(r<0)SH.cols[c]=i.value;else{(SH.d[r]=SH.d[r]||[])[c]=i.value}setTimeout(()=>{$('#shw').innerHTML=shGrid();$('#savest')&&($('#savest').innerHTML='<i></i>Saved just now')})}});
document.addEventListener('keydown',e=>{if(e.target.id==='fbar'&&e.key==='Enter'&&curCell){const r=+curCell.dataset.r,c=+curCell.dataset.c;if(r>=0){(SH.d[r]=SH.d[r]||[])[c]=e.target.value;$('#shw').innerHTML=shGrid();toast('Updated.','ok',1000)}}
 if(e.target.closest?.('.sheet')&&e.key==='Enter'){e.preventDefault();const r=+e.target.dataset.r,c=+e.target.dataset.c;e.target.blur();setTimeout(()=>$(`.sheet input[data-r="${r+1}"][data-c="${c}"]`)?.focus(),30)}});
let dc=0;
addEventListener('dragenter',e=>{if(RT.a!=='drive'||!$('#dropov')||!e.dataTransfer?.types?.includes('Files'))return;e.preventDefault();dc++;$('#dropov').classList.add('on')});
addEventListener('dragover',e=>{if(RT.a==='drive'&&$('#dropov'))e.preventDefault()});
addEventListener('dragleave',()=>{if(RT.a!=='drive'||!$('#dropov'))return;if(--dc<=0){dc=0;$('#dropov').classList.remove('on')}});
addEventListener('drop',e=>{if(RT.a!=='drive'||!$('#dropov'))return;e.preventDefault();dc=0;$('#dropov').classList.remove('on');const n=[...(e.dataTransfer?.files||[])].map(f=>f.name);if(n.length)dUpload(n)});
